#include <bits/stdc++.h>
using namespace std;
// components -> intervals -> overlap graph; answer = components - groups
int main() { int n, m; cin >> n >> m; vector<int> p(n + 1); iota(p.begin(), p.end(), 0); function<int(int)> f = [&](int x) { return p[x] == x ? x : p[x] = f(p[x]); }; for (int i = 0; i < m; i++) { int a, b; cin >> a >> b; p[f(a)] = f(b); } map<int, pair<int,int>> iv; for (int v = 1; v <= n; v++) { int r = f(v); if (!iv.count(r)) iv[r] = {v, v}; iv[r].first = min(iv[r].first, v); iv[r].second = max(iv[r].second, v); } vector<pair<int,int>> I; for (auto& [k, x] : iv) I.push_back(x); int k = I.size(); vector<int> g(k); iota(g.begin(), g.end(), 0); function<int(int)> fg = [&](int x) { return g[x] == x ? x : g[x] = fg(g[x]); }; for (int i = 0; i < k; i++) for (int j = 0; j < k; j++) if (max(I[i].first, I[j].first) <= min(I[i].second, I[j].second)) g[fg(i)] = fg(j); int groups = 0; for (int i = 0; i < k; i++) if (fg(i) == i) groups++; cout << k - groups << "\n"; }
